import{_ as d,c as a,o as e,a0 as i}from"./chunks/framework.CAcMrZkh.js";const u=JSON.parse('{"title":"移动端部署 - Uni-App 多端分发","description":"BearPlan 移动端基于 Uni-App，一套代码编译到 H5、微信/支付宝小程序、Android/iOS App、鸿蒙多个平台，各平台构建方式、产物格式与分发渠道不同，需分别处理。","frontmatter":{"title":"移动端部署 - Uni-App 多端分发","description":"BearPlan 移动端基于 Uni-App，一套代码编译到 H5、微信/支付宝小程序、Android/iOS App、鸿蒙多个平台，各平台构建方式、产物格式与分发渠道不同，需分别处理。"},"headers":[],"relativePath":"bearplan/deploy-mobile.md","filePath":"bearplan/deploy-mobile.md"}'),o={name:"bearplan/deploy-mobile.md"};function r(l,t,n,p,s,c){return e(),a("div",null,t[0]||(t[0]=[i('<h1 id="移动端部署" tabindex="-1">移动端部署 <a class="header-anchor" href="#移动端部署" aria-label="Permalink to &quot;移动端部署&quot;">​</a></h1><div class="warning custom-block"><p class="custom-block-title">🚧 开发中</p><p>本章节内容正在撰写中，暂未完成。下方先介绍多端构建与分发的基础思路，完整教程随后补充。</p></div><p>BearPlan 移动端基于 Uni-App，一套代码可编译到多个平台。不同平台的构建方式、产物格式和分发渠道完全不同，需要分别处理。</p><h2 id="多端目标" tabindex="-1">多端目标 <a class="header-anchor" href="#多端目标" aria-label="Permalink to &quot;多端目标&quot;">​</a></h2><table tabindex="0"><thead><tr><th>平台</th><th>构建命令</th><th>产物</th><th>分发方式</th></tr></thead><tbody><tr><td><strong>H5</strong></td><td><code>uni build -p h5</code></td><td>静态文件</td><td>nginx / CDN 托管</td></tr><tr><td><strong>微信小程序</strong></td><td><code>uni build -p mp-weixin</code></td><td>小程序代码包</td><td>微信开发者工具上传 + 提审</td></tr><tr><td><strong>支付宝小程序</strong></td><td><code>uni build -p mp-alipay</code></td><td>小程序代码包</td><td>支付宝 IDE 上传 + 提审</td></tr><tr><td><strong>Android App</strong></td><td><code>uni build -p app</code> + HBuilderX 打包</td><td>APK / AAB</td><td>应用市场 / 自有渠道分发</td></tr><tr><td><strong>iOS App</strong></td><td><code>uni build -p app</code> + 云打包 / 本地打包</td><td>IPA</td><td>App Store / TestFlight</td></tr><tr><td><strong>鸿蒙（HarmonyOS）</strong></td><td>HBuilderX 鸿蒙打包</td><td>APP 包</td><td>华为应用市场</td></tr></tbody></table><h2 id="分发方式预告" tabindex="-1">分发方式预告 <a class="header-anchor" href="#分发方式预告" aria-label="Permalink to &quot;分发方式预告&quot;">​</a></h2><h3 id="h5-端" tabindex="-1">H5 端 <a class="header-anchor" href="#h5-端" aria-label="Permalink to &quot;H5 端&quot;">​</a></h3><p>与前端 Admin 部署方式一致——静态文件托管，配置 nginx / CDN 即可。通常挂在 <code>m.domain.com</code> 或 <code>h5.domain.com</code> 子域名。</p><h3 id="小程序端" tabindex="-1">小程序端 <a class="header-anchor" href="#小程序端" aria-label="Permalink to &quot;小程序端&quot;">​</a></h3><p>Uni-App 编译产出小程序代码包后：</p><ol><li>用对应平台的开发者工具打开 <code>dist/build/mp-weixin</code> 等目录。</li><li>在工具内点「上传」，填写版本号和备注。</li><li>到小程序管理后台提交审核，通过后发布。</li></ol><p>注意小程序需在后台配置 <strong>request 合法域名</strong>（后端 API 地址，必须是 HTTPS）。</p><h3 id="app-端" tabindex="-1">App 端 <a class="header-anchor" href="#app-端" aria-label="Permalink to &quot;App 端&quot;">​</a></h3><ul><li><strong>云打包</strong>：HBuilderX 提交打包参数到 DCloud 云端，生成 APK / IPA。简单但依赖第三方。</li><li><strong>本地打包</strong>：离线集成 Uni-App SDK 到原生工程，适合需要原生定制或保护证书的场景。</li></ul><h2 id="待完善内容" tabindex="-1">待完善内容 <a class="header-anchor" href="#待完善内容" aria-label="Permalink to &quot;待完善内容&quot;">​</a></h2><p>完整教程将补充：</p><ul><li>HBuilderX CLI 命令行构建（脱离 GUI，支持 CI/CD）</li><li>各平台环境配置（小程序 AppID、App 证书、签名）</li><li>CI/CD 自动化构建（GitHub Actions / Gitee Go 多平台矩阵构建）</li><li>版本号管理与多环境配置（测试 / 预发 / 生产）</li><li>热更新方案（App 端 wgt 资源热更新）</li></ul><p>敬请期待。</p>',18)]))}const b=d(o,[["render",r]]);export{u as __pageData,b as default};
